import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

@WebServlet("/report")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sortCol = req.getParameter("sort");

        if (reportId == null || !reportId.matches("[0-9]+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Template-based query construction for flexible sorting
        Map<String, String> params = new HashMap<>();
        params.put("report_id", reportId);
        params.put("sort_column", sortCol != null ? sortCol : "created_at");
        params.put("format", format != null ? format : "json");

        String queryTemplate = "SELECT r.id, r.title, r.content, r.created_at, u.name as author "
            + "FROM reports r JOIN users u ON r.author_id = u.id "
            + "WHERE r.id = ${report_id} "
            + "ORDER BY ${sort_column} DESC";

        StringSubstitutor sub = new StringSubstitutor(params);
        String finalQuery = sub.replace(queryTemplate);

        log.info("Executing report query for id=" + reportId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            if (rs.next()) {
                out.print("\"id\":" + rs.getInt("id") + ",");
                out.print("\"title\":\"" + escapeJson(rs.getString("title")) + "\",");
                out.print("\"content\":\"" + escapeJson(rs.getString("content")) + "\",");
                out.print("\"author\":\"" + escapeJson(rs.getString("author")) + "\",");
                out.print("\"created_at\":\"" + rs.getTimestamp("created_at") + "\"");
            }
            out.print("}");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch report generation - admin only (checked by upstream auth)
        String ids = req.getParameter("ids");
        String query = "SELECT id, title FROM reports WHERE id IN (" + ids + ")";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.print("{\"id\":" + rs.getInt("id") + ",");
                out.print("\"title\":\"" + escapeJson(rs.getString("title")) + "\"}");
                first = false;
            }
            out.print("]");
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
